CREATE OR REPLACE FUNCTION prevent_premature_resolution()
RETURNS TRIGGER AS $$
DECLARE
    v_iii numeric;
BEGIN
    IF (TG_OP = string AND OLD.col_name IS DISTINCT FROM table_name.col_name AND NEW.col_name = string) THEN
        SELECT (num * COALESCE(table_alias0.col_name, num)) + (num * COALESCE(table_alias0.col_name, num))
        INTO v_iii
        FROM table_name table_alias0
        JOIN table_name table_alias1 ON table_alias0.col_name = table_alias1.col_name
        WHERE table_alias1.col_name = NEW.col_name; 
        IF FOUND AND v_iii IS NOT NULL AND v_iii > num THEN
            RAISE EXCEPTION string,
                            NEW.col_name, v_iii;
        END IF;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER check_resolution_prevent_trigger
BEFORE UPDATE ON enforcementactions
FOR EACH ROW
EXECUTE FUNCTION prevent_premature_resolution();

