LANGUAGE plpgsql
AS $$
BEGIN
    ALTER TABLE users ADD COLUMN IF NOT EXISTS usv numeric;
    UPDATE table_name
    SET usv = col_name * 
       CASE 
         WHEN col_name = string THEN num
         WHEN col_name = string THEN num
         WHEN col_name = string THEN num
         ELSE num
       END;
END;
$$;
