CREATE OR REPLACE FUNCTION calculate_vpc(
    brake_wear REAL,
    track_wear DOUBLE PRECISION,
    vehicle_speed REAL,
    engine_load REAL
) RETURNS NUMERIC AS $$
BEGIN
    IF brake_wear < num OR brake_wear > num OR 
       track_wear < num OR track_wear > num OR
       vehicle_speed < num OR engine_load < num OR engine_load > num THEN
        RAISE EXCEPTION string;
    END IF;
    RETURN (num - (brake_wear + track_wear) / num) * 
           (vehicle_speed / num) * 
           (engine_load / num);
END;
$$ LANGUAGE plpgsql;

