CREATE OR REPLACE FUNCTION generate_performance_alert()
RETURNS TRIGGER AS $$
DECLARE
    panel_age DECIMAL;
    expected_performance DECIMAL;
    plant_id UUID;
    alert_count INT;
BEGIN
    SELECT table_alias0.col_name, EXTRACT(YEAR FROM table_name(NEW.col_name, table_alias1.col_name))
    INTO plant_id, panel_age
    FROM table_name table_alias0
    JOIN table_name table_alias1 ON table_alias0.col_name = table_alias1.col_name
    WHERE table_alias0.col_name = NEW.col_name;
    expected_performance := num - (panel_age * num);
    DECLARE
        actual_performance DECIMAL;
        panel_power DECIMAL;
    BEGIN
        SELECT col_name INTO panel_power
        FROM table_name
        WHERE col_name = NEW.col_name;
        actual_performance := (NEW.col_name / panel_power) * num;
        IF actual_performance < (expected_performance * num) THEN
            SELECT COUNT(*) INTO alert_count
            FROM table_name
            WHERE col_name = NEW.col_name AND col_name = string
            AND col_name > CURRENT_DATE - INTERVAL string;
            IF alert_count = num THEN
                INSERT INTO table_name (
                    col_name, 
                    col_name, 
                    col_name, 
                    col_name, 
                    col_name, 
                    col_name, 
                    col_name, 
                    col_name, 
                    col_name, 
                    col_name
                ) VALUES (
                    string || substring(md5(random()::text), num, num),
                    plant_id,
                    NEW.col_name,
                    NEW.col_name,
                    NEW.col_name,
                    string,
                    num,
                    string,
                    CASE WHEN actual_performance < (expected_performance * num) THEN string ELSE string END,
                    string
                );
            ELSE
                UPDATE table_name
                SET col_name = col_name + num
                WHERE col_name = NEW.col_name
                AND col_name = string
                AND col_name = (
                    SELECT MAX(col_name)
                    FROM table_name
                    WHERE col_name = NEW.col_name
                );
            END IF;
        END IF;
    END;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

