CREATE OR REPLACE FUNCTION calculate_rcp(p_vehiclereg VARCHAR)
RETURNS NUMERIC AS $$
DECLARE
    v_dist_done NUMERIC;
    v_dist_left NUMERIC;
    v_rcp NUMERIC;
BEGIN
    -- Step 1: Select distance done and distance left for the given vehicle.
    SELECT distdonekm, distleftkm
    INTO v_dist_done, v_dist_left
    FROM transportinfo
    WHERE vehiclereg = p_vehiclereg;

    -- Step 2: Calculate RCP = DistDoneKm / (DistDoneKm + DistLeftKm) * 100.
    --         Handle cases where data is missing or total distance is zero.
    IF FOUND AND v_dist_done IS NOT NULL AND v_dist_left IS NOT NULL AND (v_dist_done + v_dist_left) > 0 THEN
        v_rcp := (v_dist_done / (v_dist_done + v_dist_left)) * 100.0;
    ELSE
        v_rcp := NULL; -- Or 0, depending on desired output for invalid/missing data
    END IF;

    -- Step 3: Return the calculated RCP.
    RETURN v_rcp;
END;
$$ LANGUAGE plpgsql

canonical_sql:
CREATE OR REPLACE FUNCTION calculate_rcp(p_vehiclereg VARCHAR)
RETURNS NUMERIC AS $$
DECLARE
    v_dist_done NUMERIC;
    v_dist_left NUMERIC;
    v_rcp NUMERIC;
BEGIN
    SELECT col_name, col_name
    INTO v_dist_done, v_dist_left
    FROM table_name
    WHERE col_name = p_vehiclereg;
    IF FOUND AND v_dist_done IS NOT NULL AND v_dist_left IS NOT NULL AND (v_dist_done + v_dist_left) > num THEN
        v_rcp := (v_dist_done / (v_dist_done + v_dist_left)) * num;
    ELSE
        v_rcp := NULL; 
    END IF;
    RETURN v_rcp;
END;
$$ LANGUAGE plpgsql

CREATE OR REPLACE FUNCTION calculate_fei(
    eng_rate DECIMAL,
    social_score DECIMAL,
    active_days SMALLINT,
    avg_sessions SMALLINT
) RETURNS DECIMAL AS $$
BEGIN
    RETURN (eng_rate * num) + 
           (social_score / num * num) + 
           (active_days::DECIMAL / num * num) + 
           (avg_sessions::DECIMAL / num * num);
END;
$$ LANGUAGE plpgsql;

